/*
 * Phase 5 container-query whitelist member: the root is the query container
 * and the inner frame consumes it, so chrome morphs with the shell's own
 * inline size rather than the raw viewport.
 *
 * Three-end path: one `.cu-app-shell__nav` cell. Compact docks it to the
 * block-end and keeps it there while main scrolls; 48rem/80rem move the same
 * cell to the side column. Do not mount Sidebar + TabBar for that job — use
 * Navigation.
 *
 * Legacy `sidebar` / `tab-bar` slots remain for specialized single-form chrome.
 * Nested previews must override block-size / max-block-size. The shell fills
 * its parent (html/body/#root at 100%, or the remaining flex row under demo
 * chrome). Do not lock min-block-size to 100dvh — that overflows any parent
 * shorter than the viewport and clips the compact nav off-screen.
 */
.cu-app-shell {
  container-name: app-shell;
  container-type: inline-size;
  display: flex;
  flex-direction: column;
  block-size: 100%;
  min-block-size: 0;
  max-block-size: 100%;
  overflow: hidden;
  color: var(--cu-color-fg-default);
  background: var(--cu-color-background-subtle, var(--cu-color-background-default));
}

.cu-app-shell__frame {
  display: grid;
  flex: 1 1 0;
  grid-template-areas:
    "header"
    "main";
  grid-template-columns: 1fr;
  grid-template-rows: auto minmax(0, 1fr);
  block-size: 100%;
  min-block-size: 0;
  max-block-size: 100%;
  overflow: hidden;
}

.cu-app-shell:has(.cu-app-shell__nav) .cu-app-shell__frame {
  grid-template-areas:
    "header"
    "main"
    "nav";
  grid-template-rows: auto minmax(0, 1fr) auto;
}

.cu-app-shell:has(.cu-app-shell__tab-bar):not(:has(.cu-app-shell__nav)) .cu-app-shell__frame {
  grid-template-areas:
    "header"
    "main"
    "tabbar";
  grid-template-rows: auto minmax(0, 1fr) auto;
}

.cu-app-shell__header {
  grid-area: header;
  position: sticky;
  inset-block-start: 0;
  z-index: 8;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  background: var(
    --cu-color-background-translucent,
    var(--cu-color-background-elevated, var(--cu-color-background-default))
  );
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost, 1)) blur(var(--cu-blur-surface, 0px));
  backdrop-filter: saturate(var(--cu-saturate-frost, 1)) blur(var(--cu-blur-surface, 0px));
  border-block-end: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
}

.cu-app-shell__header:has(.cu-navigation-bar) {
  padding-block: 0;
  padding-inline: 0;
}

.cu-app-shell__nav {
  grid-area: nav;
  position: sticky;
  inset-block-end: 0;
  z-index: 9;
  flex-shrink: 0;
}

.cu-app-shell__sidebar {
  display: none;
  grid-area: sidebar;
  padding-block: var(--cu-space-4, var(--cu-space-3));
  padding-inline: var(--cu-space-3);
  background: var(--cu-color-background-elevated, var(--cu-color-background-default));
  border-inline-end: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
}

.cu-app-shell__main {
  grid-area: main;
  min-block-size: 0;
  padding-block: var(--cu-space-5, var(--cu-space-3));
  padding-inline: var(--cu-space-5, var(--cu-space-3));
  overflow-x: hidden;
  overflow-y: auto;
  scrollbar-gutter: stable;
  contain: layout style;
  overscroll-behavior: contain;
  background: var(--cu-color-background-subtle, var(--cu-color-background-default));
}

.cu-app-shell__tab-bar {
  grid-area: tabbar;
  position: sticky;
  inset-block-end: 0;
  z-index: 9;
}

.cu-app-shell__tab-bar .cu-tab-bar {
  position: relative;
  inset: auto;
  z-index: 2;
}

/* 48rem == breakpoint.tablet, 80rem == breakpoint.desktop (tokens/src/core/breakpoint.json). */
@container (min-width: 48rem) {
  .cu-app-shell:has(.cu-app-shell__nav) .cu-app-shell__frame {
    grid-template-areas:
      "nav header"
      "nav main";
    grid-template-columns: 12rem 1fr;
    grid-template-rows: auto minmax(0, 1fr);
  }

  .cu-app-shell:has(.cu-app-shell__sidebar):not(:has(.cu-app-shell__nav)) .cu-app-shell__frame {
    grid-template-areas:
      "sidebar header"
      "sidebar main";
    grid-template-columns: 12rem 1fr;
    grid-template-rows: auto minmax(0, 1fr);
  }

  .cu-app-shell:has(.cu-app-shell__tab-bar):has(.cu-app-shell__sidebar):not(:has(.cu-app-shell__nav)) .cu-app-shell__frame {
    grid-template-areas:
      "sidebar header"
      "sidebar main"
      "tabbar tabbar";
    grid-template-columns: 12rem 1fr;
    grid-template-rows: auto minmax(0, 1fr) auto;
  }

  .cu-app-shell__sidebar {
    display: block;
    position: sticky;
    inset-block-start: 0;
    inset-inline-start: 0;
    align-self: stretch;
    min-block-size: 0;
    overflow: auto;
  }

  .cu-app-shell__nav {
    position: sticky;
    inset-block-start: 0;
    inset-inline-start: 0;
    inset-block-end: auto;
    align-self: stretch;
    min-block-size: 0;
    overflow: auto;
  }
}

@container (min-width: 80rem) {
  .cu-app-shell:has(.cu-app-shell__nav) .cu-app-shell__frame {
    grid-template-areas:
      "nav header"
      "nav main";
    grid-template-columns: 16rem 1fr;
    grid-template-rows: auto minmax(0, 1fr);
  }

  .cu-app-shell:has(.cu-app-shell__sidebar):not(:has(.cu-app-shell__nav)) .cu-app-shell__frame,
  .cu-app-shell:has(.cu-app-shell__tab-bar):has(.cu-app-shell__sidebar):not(:has(.cu-app-shell__nav)) .cu-app-shell__frame {
    grid-template-areas:
      "sidebar header"
      "sidebar main";
    grid-template-columns: 16rem 1fr;
    grid-template-rows: auto minmax(0, 1fr);
  }

  .cu-app-shell__tab-bar {
    display: none;
  }
}
